/**
 * This event is fired on the {@link MinecraftForge#EVENT_BUS}.<br>
 * This event is fired when a projectile entity impacts something.<br>
 * This event is fired via {@link ForgeEventFactory#onProjectileImpact(Projectile, HitResult)}
 * This event is fired for all vanilla projectiles by Forge,
 * custom projectiles should fire this event and check the result in a similar fashion.
 * This event is cancelable. When canceled, the impact will not be processed and the projectile will continue flying.
 * Killing or other handling of the entity after event cancellation is up to the modder.
 * You can also directly set the {@link ImpactResult} to change the impact behaviour.
 * @see #setImpactResult(ImpactResult)
 */
@Cancelable
public class ProjectileImpactEvent extends EntityEvent
{
    private final HitResult ray;
    private final Projectile projectile;

    private ImpactResult result = ImpactResult.DEFAULT;

    public ProjectileImpactEvent(Projectile projectile, HitResult ray)
    {
        super(projectile);
        this.ray = ray;
        this.projectile = projectile;
    }

    /**
     * {@inheritDoc}
     * @deprecated Use {@link #setImpactResult(ImpactResult)} instead.
     */
    @Deprecated(forRemoval = true, since = "1.20.1")
    public void setCanceled(boolean cancel)
    {
        super.setCanceled(cancel);
    }

    public HitResult getRayTraceResult()
    {
        return ray;
    }

    public Projectile getProjectile()
    {
        return projectile;
    }

    public void setImpactResult(@NotNull ImpactResult newResult)
    {
        this.result = Objects.requireNonNull(newResult, "ImpactResult cannot be null");
    }

    public ImpactResult getImpactResult()
    {
        return result;
    }

    public enum ImpactResult
    {
        /**
         * The default behaviour, the projectile will be destroyed and the hit will be processed.
         */
        DEFAULT,
        /**
         * The projectile will pass through the current entity as if it wasn't there. This will return default behaviour if there is no entity.
         */
        SKIP_ENTITY,
        /**
         * Damage the entity and stop the projectile here, the projectile will not pierce.
         */
        STOP_AT_CURRENT,
        /**
         * Cancel the piercing aspect of the projectile, and do not damage the entity.
         */
        STOP_AT_CURRENT_NO_DAMAGE
    }
}

public InteractionResult useItem(ServerPlayer p_9262_, Level p_9263_, ItemStack p_9264_, InteractionHand p_9265_) {
   if (this.gameModeForPlayer == GameType.SPECTATOR) {
      return InteractionResult.PASS;
   } else if (p_9262_.getCooldowns().isOnCooldown(p_9264_.getItem())) {
      return InteractionResult.PASS;
   } else {
      InteractionResult cancelResult = net.minecraftforge.common.ForgeHooks.onItemRightClick(p_9262_, p_9265_);
      if (cancelResult != null) return cancelResult;
      int i = p_9264_.getCount();
      int j = p_9264_.getDamageValue();
      InteractionResultHolder<ItemStack> interactionresultholder = p_9264_.use(p_9263_, p_9262_, p_9265_);
      ItemStack itemstack = interactionresultholder.getObject();
      if (itemstack == p_9264_ && itemstack.getCount() == i && itemstack.getUseDuration() <= 0 && itemstack.getDamageValue() == j) {
         return interactionresultholder.getResult();
      } else if (interactionresultholder.getResult() == InteractionResult.FAIL && itemstack.getUseDuration() > 0 && !p_9262_.isUsingItem()) {
         return interactionresultholder.getResult();
      } else {
         if (p_9264_ != itemstack) {
            p_9262_.setItemInHand(p_9265_, itemstack);
         }

         if (this.isCreative() && itemstack != ItemStack.EMPTY) {
            itemstack.setCount(i);
            if (itemstack.isDamageableItem() && itemstack.getDamageValue() != j) {
               itemstack.setDamageValue(j);
            }
         }

         if (itemstack.isEmpty()) {
            p_9262_.setItemInHand(p_9265_, ItemStack.EMPTY);
         }

         if (!p_9262_.isUsingItem()) {
            p_9262_.inventoryMenu.sendAllDataToRemote();
         }

         return interactionresultholder.getResult();
      }
   }
}

public void handleUseItem(ServerboundUseItemPacket p_9932_) {
   PacketUtils.ensureRunningOnSameThread(p_9932_, this, this.player.serverLevel());
   this.ackBlockChangesUpTo(p_9932_.getSequence());
   ServerLevel serverlevel = this.player.serverLevel();
   InteractionHand interactionhand = p_9932_.getHand();
   ItemStack itemstack = this.player.getItemInHand(interactionhand);
   this.player.resetLastActionTime();
   if (!itemstack.isEmpty() && itemstack.isItemEnabled(serverlevel.enabledFeatures())) {
      InteractionResult interactionresult = this.player.gameMode.useItem(this.player, serverlevel, itemstack, interactionhand);
      if (interactionresult.shouldSwing()) {
         this.player.swing(interactionhand, true);
      }

   }
}

